function Reveal({ children, className = "", delay = 0 }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisible(true);
            obs.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.15 },
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return (
    <div
      ref={ref}
      className={`reveal ${visible ? "reveal-visible" : ""} ${className}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {children}
    </div>
  );
}

export default function App() {
  const [theme, setTheme] = useState("dark");
  const [lang, setLang] = useState("ar");
  const [menuOpen, setMenuOpen] = useState(false);
  const t = content[lang];

  const mountRef = useRef(null);
  const lineMatRef = useRef(null);
  const particleMatRef = useRef(null);

  useEffect(() => {
    const container = mountRef.current;
    if (!container) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(50, width / height, 0.1, 1000);
    camera.position.z = 6.4;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    container.appendChild(renderer.domElement);

    const geo = new THREE.IcosahedronGeometry(2.15, 1);
    const wireGeo = new THREE.WireframeGeometry(geo);
    const lineMat = new THREE.LineBasicMaterial({
      color: 0xe7b65c,
      transparent: true,
      opacity: 0.9,
    });
    const wireMesh = new THREE.LineSegments(wireGeo, lineMat);
    scene.add(wireMesh);
    lineMatRef.current = lineMat;

    const innerGeo = new THREE.IcosahedronGeometry(1.1, 0);
    const innerWire = new THREE.WireframeGeometry(innerGeo);
    const innerMat = new THREE.LineBasicMaterial({
      color: 0xe7b65c,
      transparent: true,
      opacity: 0.35,
    });
    const innerMesh = new THREE.LineSegments(innerWire, innerMat);
    scene.add(innerMesh);

    const particleCount = 260;
    const positions = new Float32Array(particleCount * 3);
    for (let i = 0; i < particleCount; i++) {
      positions[i * 3] = (Math.random() - 0.5) * 15;
      positions[i * 3 + 1] = (Math.random() - 0.5) * 15;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 15;
    }
    const particleGeo = new THREE.BufferGeometry();
    particleGeo.setAttribute(
      "position",
      new THREE.BufferAttribute(positions, 3),
    );
    const particleMat = new THREE.PointsMaterial({
      color: 0xe7b65c,
      size: 0.035,
      transparent: true,
      opacity: 0.55,
    });
    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);
    particleMatRef.current = particleMat;

    let mouseX = 0;
    let mouseY = 0;
    const handleMouseMove = (e) => {
      const rect = container.getBoundingClientRect();
      mouseX = (e.clientX - rect.left) / rect.width - 0.5;
      mouseY = (e.clientY - rect.top) / rect.height - 0.5;
    };
    container.addEventListener("mousemove", handleMouseMove);

    let frameId;
    const animate = () => {
      wireMesh.rotation.x += 0.0017;
      wireMesh.rotation.y += 0.0025;
      innerMesh.rotation.x -= 0.001;
      innerMesh.rotation.y -= 0.0018;
      particles.rotation.y += 0.0006;
      camera.position.x += (mouseX * 1.3 - camera.position.x) * 0.02;
      camera.position.y += (-mouseY * 1.3 - camera.position.y) * 0.02;
      camera.lookAt(0, 0, 0);
      renderer.render(scene, camera);
      frameId = requestAnimationFrame(animate);
    };
    animate();

    const handleResize = () => {
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", handleResize);

    return () => {
      cancelAnimationFrame(frameId);
      window.removeEventListener("resize", handleResize);
      container.removeEventListener("mousemove", handleMouseMove);
      renderer.dispose();
      geo.dispose();
      wireGeo.dispose();
      lineMat.dispose();
      innerGeo.dispose();
      innerWire.dispose();
      innerMat.dispose();
      particleGeo.dispose();
      particleMat.dispose();
      if (container.contains(renderer.domElement))
        container.removeChild(renderer.domElement);
    };
  }, []);

  useEffect(() => {
    const hex = theme === "dark" ? 0xe7b65c : 0xc9832e;
    if (lineMatRef.current) lineMatRef.current.color.setHex(hex);
    if (particleMatRef.current) particleMatRef.current.color.setHex(hex);
  }, [theme]);

  const scrollTo = (id) => {
    setMenuOpen(false);
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <div className="site" data-theme={theme} dir={t.dir}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

        .site {
          --bg: #0B0E14; --surface: #12161F; --line: #2A3242;
          --text: #E7E5DE; --text-dim: #9AA1AE;
          --accent: #E7B65C; --accent-dim: #6b5a34; --accent-ink: #1A1305;
          font-family: 'IBM Plex Sans Arabic', sans-serif;
          background: var(--bg); color: var(--text);
          line-height: 1.7; min-height: 100vh; transition: background .4s ease, color .4s ease;
        }
        .site[data-theme='light'] {
          --bg: #EDEEF2; --surface: #FFFFFF; --line: #D8DCE3;
          --text: #171B22; --text-dim: #5B6472;
          --accent: #C9832E; --accent-dim: #ecd3a8; --accent-ink: #FFF6E8;
        }
        .site * { box-sizing: border-box; }
        .site a { color: inherit; text-decoration: none; }
        .mono { font-family: 'JetBrains Mono', monospace; letter-spacing: 0.02em; }
        .wrap { max-width: 1120px; margin: 0 auto; padding: 0 28px; }

        .reveal { opacity: 0; transform: translateY(24px); transition: opacity .7s ease, transform .7s ease; }
        .reveal-visible { opacity: 1; transform: translateY(0); }

        header { position: sticky; top: 0; z-index: 50; background: color-mix(in srgb, var(--bg) 85%, transparent); backdrop-filter: blur(8px); border-bottom: 1px solid var(--line); }
        .nav-row { display: flex; align-items: center; justify-content: space-between; padding: 18px 0; gap: 16px; }
        .brand { display: flex; align-items: center; gap: 10px; font-size: 1.02rem; font-weight: 600; }
        .brand-mark { width: 10px; height: 10px; background: var(--accent); flex-shrink: 0; }
        .brand-logo { width: 30px; height: 30px; object-fit: cover; border-radius: 6px; flex-shrink: 0; }
        .footer-logo { width: 24px; height: 24px; object-fit: cover; border-radius: 5px; }
        .work-note { color: var(--text-dim); font-size: 0.88rem; max-width: 64ch; margin: 14px 0 0; width: 100%; }
        .work-gallery { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 18px; }
        .work-gallery img { width: 150px; height: 74px; object-fit: cover; border: 1px solid var(--line); background: var(--bg); transition: transform .25s ease, border-color .25s ease; }
        .work-gallery img:hover { transform: translateY(-3px); border-color: var(--accent); }
        .brand span.mono { font-size: 0.7rem; color: var(--text-dim); }
        nav ul { display: flex; gap: 30px; list-style: none; }
        nav button.link { background: none; border: none; font-size: 0.95rem; color: var(--text-dim); cursor: pointer; font-family: inherit; transition: color .2s; }
        nav button.link:hover { color: var(--text); }
        .nav-tools { display: flex; align-items: center; gap: 10px; }
        .icon-btn { display: flex; align-items: center; justify-content: center; width: 38px; height: 38px; border: 1px solid var(--line); background: none; color: var(--text); cursor: pointer; transition: border-color .2s, color .2s; }
        .icon-btn:hover { border-color: var(--accent); color: var(--accent); }
        .lang-btn { display: flex; align-items: center; gap: 6px; padding: 0 12px; width: auto; font-size: 0.82rem; font-family: 'JetBrains Mono', monospace; }
        .nav-cta { border: 1px solid var(--accent-dim); color: var(--accent); padding: 8px 18px; font-size: 0.86rem; white-space: nowrap; transition: background .2s, color .2s; }
        .nav-cta:hover { background: var(--accent); color: var(--accent-ink); }
        .menu-btn { display: none; }

        .hero { position: relative; overflow: hidden; border-bottom: 1px solid var(--line); }
        .hero-3d { position: absolute; inset: 0; z-index: 0; opacity: 0.9; mask-image: radial-gradient(ellipse 75% 65% at 50% 30%, black 35%, transparent 88%); -webkit-mask-image: radial-gradient(ellipse 75% 65% at 50% 30%, black 35%, transparent 88%); }
        .hero-inner { position: relative; z-index: 1; padding: 110px 0 90px; pointer-events: none; }
        .hero-inner a, .hero-inner button { pointer-events: auto; }
        .hero-eyebrow { font-size: 0.82rem; color: var(--accent); margin-bottom: 22px; display: flex; align-items: center; gap: 10px; }
        .hero-eyebrow .rule { width: 34px; height: 1px; background: var(--accent-dim); }
        h1.hero-title { font-size: clamp(2.1rem, 5vw, 3.5rem); font-weight: 600; line-height: 1.28; max-width: 16ch; }
        .hero-sub { margin-top: 26px; max-width: 58ch; color: var(--text-dim); font-size: 1.06rem; }
        .hero-actions { margin-top: 40px; display: flex; gap: 16px; flex-wrap: wrap; }
        .btn-primary { background: var(--accent); color: var(--accent-ink); padding: 14px 26px; font-weight: 600; font-size: 0.95rem; border: none; cursor: pointer; font-family: inherit; transition: transform .2s ease, filter .2s ease; }
        .btn-primary:hover { transform: translateY(-2px); filter: brightness(1.08); }
        .btn-ghost { border: 1px solid var(--line); color: var(--text); padding: 14px 26px; font-size: 0.95rem; background: none; cursor: pointer; font-family: inherit; transition: border-color .2s ease, transform .2s ease; }
        .btn-ghost:hover { border-color: var(--text-dim); transform: translateY(-2px); }

        .hero-stats { margin-top: 70px; display: flex; border-top: 1px solid var(--line); }
        .stat { flex: 1 1 160px; padding: 20px 24px 0; border-inline-start: 1px solid var(--line); }
        .stat:first-child { border-inline-start: none; padding-inline-start: 0; }
        .stat .num { font-size: 1.6rem; color: var(--accent); font-weight: 600; }
        .stat .lbl { font-size: 0.82rem; color: var(--text-dim); margin-top: 4px; }

        section { padding: 96px 0; border-bottom: 1px solid var(--line); }
        .sec-head { display: flex; align-items: baseline; justify-content: space-between; gap: 20px; margin-bottom: 56px; flex-wrap: wrap; }
        .sec-head h2 { font-size: clamp(1.45rem, 3vw, 2.05rem); font-weight: 600; }
        .sec-head .sec-tag { font-size: 0.8rem; color: var(--text-dim); }

        .service-row { display: grid; grid-template-columns: 60px 1fr 210px; gap: 24px; padding: 28px 0; border-top: 1px solid var(--line); align-items: start; transition: padding-inline-start .3s ease; }
        .service-row:hover { padding-inline-start: 8px; }
        .service-row:last-child { border-bottom: 1px solid var(--line); }
        .service-idx { font-size: 0.94rem; color: var(--accent); padding-top: 2px; }
        .service-name { font-size: 1.16rem; font-weight: 600; margin-bottom: 8px; }
        .service-desc { color: var(--text-dim); max-width: 60ch; font-size: 0.96rem; }
        .service-stack { font-size: 0.75rem; color: var(--text-dim); }
        .service-stack span { display: inline-block; border: 1px solid var(--line); padding: 4px 9px; margin: 0 0 6px; }

        .work-list { display: flex; flex-direction: column; gap: 1px; background: var(--line); }
        .work-item { background: var(--surface); padding: 34px 30px; display: grid; grid-template-columns: 1fr auto; gap: 24px; align-items: center; transition: background .3s ease; }
        .work-item:hover { background: color-mix(in srgb, var(--surface) 90%, var(--accent) 10%); }
        .work-meta { font-size: 0.78rem; color: var(--accent); margin-bottom: 10px; }
        .work-name { font-size: 1.28rem; font-weight: 600; margin-bottom: 10px; }
        .work-desc { color: var(--text-dim); max-width: 62ch; font-size: 0.95rem; }
        .work-link { border: 1px solid var(--line); padding: 11px 20px; font-size: 0.85rem; white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; transition: border-color .2s ease, color .2s ease, gap .2s ease; }
        .work-link:hover { border-color: var(--accent); color: var(--accent); gap: 9px; }

        .process-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--line); }
        .process-item { background: var(--surface); padding: 32px 26px; transition: background .3s ease; }
        .process-item:hover { background: color-mix(in srgb, var(--surface) 90%, var(--accent) 10%); }
        .process-num { font-size: 0.76rem; color: var(--text-dim); margin-bottom: 18px; }
        .process-name { font-size: 1.06rem; font-weight: 600; margin-bottom: 10px; }
        .process-desc { font-size: 0.89rem; color: var(--text-dim); }

        .contact-panel { display: grid; grid-template-columns: 1.1fr 1fr; gap: 60px; align-items: start; }
        .contact-panel h2 { font-size: clamp(1.55rem, 3.3vw, 2.25rem); font-weight: 600; max-width: 17ch; margin-bottom: 20px; }
        .contact-panel p { color: var(--text-dim); max-width: 48ch; }
        .contact-list { display: flex; flex-direction: column; }
        .contact-row { display: flex; align-items: center; justify-content: space-between; padding: 18px 0; border-top: 1px solid var(--line); transition: gap .2s ease; }
        .contact-row:last-child { border-bottom: 1px solid var(--line); }
        .contact-left { display: flex; align-items: center; gap: 12px; color: var(--text-dim); font-size: 0.85rem; }
        .contact-value { font-size: 1rem; transition: color .2s ease; }
        .contact-row:hover .contact-value { color: var(--accent); }
        .contact-row:hover .contact-left { color: var(--accent); }

        footer { padding: 34px 0; }
        .foot-row { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 14px; font-size: 0.78rem; color: var(--text-dim); }

        :focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

        @media (max-width: 820px) {
          nav ul { display: none; }
          .menu-btn { display: flex; }
          .service-row { grid-template-columns: 36px 1fr; }
          .service-stack { grid-column: 2; margin-top: 6px; }
          .work-item { grid-template-columns: 1fr; }
          .process-grid { grid-template-columns: 1fr 1fr; }
          .contact-panel { grid-template-columns: 1fr; gap: 40px; }
          .hero-stats { flex-direction: column; }
          .stat { border-inline-start: none !important; border-top: 1px solid var(--line); padding: 16px 0 0 !important; }
          .mobile-nav { display: flex !important; }
        }
        .mobile-nav { display: none; flex-direction: column; gap: 2px; padding: 8px 0 18px; border-bottom: 1px solid var(--line); }
        .mobile-nav button { background: none; border: none; color: var(--text-dim); font-family: inherit; font-size: 0.95rem; text-align: start; padding: 10px 0; cursor: pointer; }

        @media (prefers-reduced-motion: reduce) {
          .reveal { transition: none; opacity: 1; transform: none; }
        }
      `}</style>

      <header>
        <div className="wrap nav-row">
          <div className="brand">
            <img
              src={IMAGES.logo}
              alt="Dev Squad Solutions"
              className="brand-logo"
            />
            DEV SQUAD SOLUTIONS
            <span className="mono">{t.brandTag}</span>
          </div>
          <nav>
            <ul>
              <li>
                <button className="link" onClick={() => scrollTo("services")}>
                  {t.nav.services}
                </button>
              </li>
              <li>
                <button className="link" onClick={() => scrollTo("work")}>
                  {t.nav.work}
                </button>
              </li>
              <li>
                <button className="link" onClick={() => scrollTo("process")}>
                  {t.nav.process}
                </button>
              </li>
              <li>
                <button className="link" onClick={() => scrollTo("contact")}>
                  {t.nav.contact}
                </button>
              </li>
            </ul>
          </nav>
          <div className="nav-tools">
            <button
              className="icon-btn lang-btn"
              onClick={() => setLang(lang === "ar" ? "en" : "ar")}
              aria-label="toggle language"
            >
              <Languages size={15} /> {lang === "ar" ? "EN" : "AR"}
            </button>
            <button
              className="icon-btn"
              onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
              aria-label="toggle theme"
            >
              {theme === "dark" ? <Sun size={16} /> : <Moon size={16} />}
            </button>
            <a
              className="nav-cta"
              href="https://wa.me/201508842515"
              target="_blank"
              rel="noopener noreferrer"
            >
              {t.nav.cta}
            </a>
            <button
              className="icon-btn menu-btn"
              onClick={() => setMenuOpen(!menuOpen)}
              aria-label="menu"
            >
              {menuOpen ? <X size={16} /> : <Menu size={16} />}
            </button>
          </div>
        </div>
        {menuOpen && (
          <div className="wrap mobile-nav">
            <button onClick={() => scrollTo("services")}>
              {t.nav.services}
            </button>
            <button onClick={() => scrollTo("work")}>{t.nav.work}</button>
            <button onClick={() => scrollTo("process")}>{t.nav.process}</button>
            <button onClick={() => scrollTo("contact")}>{t.nav.contact}</button>
          </div>
        )}
      </header>

      <section className="hero">
        <div ref={mountRef} className="hero-3d" style={{ height: "620px" }} />
        <div className="wrap hero-inner">
          <div className="hero-eyebrow">
            <span className="rule"></span> {t.hero.eyebrow}
          </div>
          <h1 className="hero-title">{t.hero.title}</h1>
          <p className="hero-sub">{t.hero.sub}</p>
          <div className="hero-actions">
            <a
              className="btn-primary"
              href="https://wa.me/201508842515"
              target="_blank"
              rel="noopener noreferrer"
            >
              {t.hero.primary}
            </a>
            <button className="btn-ghost" onClick={() => scrollTo("work")}>
              {t.hero.secondary}
            </button>
          </div>
          <div className="hero-stats">
            {t.hero.stats.map((s, i) => (
              <div className="stat" key={i}>
                <div className="num">{s.num}</div>
                <div className="lbl">{s.lbl}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section id="services">
        <div className="wrap">
          <div className="sec-head">
            <h2>{t.servicesHead.title}</h2>
            <div className="sec-tag mono">{t.servicesHead.tag}</div>
          </div>
          {t.services.map((s, i) => (
            <Reveal key={i} delay={i * 40}>
              <div className="service-row">
                <div className="service-idx mono">
                  {String(i + 1).padStart(2, "0")}
                </div>
                <div>
                  <div className="service-name">{s.name}</div>
                  <div className="service-desc">{s.desc}</div>
                </div>
                <div className="service-stack">
                  {s.stack.map((tag, j) => (
                    <span key={j}>{tag}</span>
                  ))}
                </div>
              </div>
            </Reveal>
          ))}
        </div>
      </section>

      <section id="work">
        <div className="wrap">
          <div className="sec-head">
            <h2>{t.workHead.title}</h2>
            <div className="sec-tag mono">{t.workHead.tag}</div>
            <p className="work-note">{t.workHead.note}</p>
          </div>
          <div className="work-list">
            {t.work.map((w, i) => (
              <Reveal key={i} delay={i * 60}>
                <div className="work-item">
                  <div>
                    <div className="work-meta mono">{w.meta}</div>
                    <div className="work-name">{w.name}</div>
                    <div className="work-desc">{w.desc}</div>
                    {w.images && w.images.length > 0 && (
                      <div className="work-gallery">
                        {w.images.map((src, j) => (
                          <img
                            key={j}
                            src={src}
                            alt={`${w.name} ${j + 1}`}
                            loading="lazy"
                          />
                        ))}
                      </div>
                    )}
                  </div>
                  <a
                    className="work-link"
                    href={w.link}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    {w.label} <ArrowUpRight size={15} />
                  </a>
                </div>
              </Reveal>
            ))}
          </div>
        </div>
      </section>

      <section id="process">
        <div className="wrap">
          <div className="sec-head">
            <h2>{t.processHead.title}</h2>
            <div className="sec-tag mono">{t.processHead.tag}</div>
          </div>
          <div className="process-grid">
            {t.process.map((p, i) => (
              <div className="process-item" key={i}>
                <div className="process-num mono">{p.num}</div>
                <div className="process-name">{p.name}</div>
                <div className="process-desc">{p.desc}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section id="contact" style={{ borderBottom: "none" }}>
        <div className="wrap contact-panel">
          <Reveal>
            <div>
              <h2>{t.contactHead.title}</h2>
              <p>{t.contactHead.sub}</p>
            </div>
          </Reveal>
          <Reveal delay={100}>
            <div className="contact-list">
              {t.contact.map((c, i) => {
                const Icon = ICONS[c.icon];
                return (
                  <a
                    className="contact-row"
                    href={c.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    key={i}
                  >
                    <span className="contact-left">
                      <Icon size={16} /> {c.label}
                    </span>
                    <span className="contact-value mono">{c.value}</span>
                  </a>
                );
              })}
            </div>
          </Reveal>
        </div>
      </section>

      <footer>
        <div className="wrap foot-row">
          <div
            className="mono"
            style={{ display: "flex", alignItems: "center", gap: 10 }}
          >
            <img
              src={IMAGES.logo}
              alt="Dev Squad Solutions"
              className="footer-logo"
            />
            {t.footer}
          </div>
        </div>
      </footer>
    </div>
  );
}
